package main

import "fmt"

func eh_primo(x int, div int) bool {

	if x < 2 {
		return false
	}
	if div == x {
		return true
	}
	if x%div == 0 {
		return false
	}

	return eh_primo(x, div+1)
	_, _ = x, div
	return false
}

func main() {
	var x int
	fmt.Scan(&x)
	if eh_primo(x, 2) {
		fmt.Println("true")
	} else {
		fmt.Println("false")
	}
}
